            old_text = self.requirements[req_id]["text"]
            self.requirements[req_id] = {"text": new_requirement_text, "developer_id": developer_id, "timestamp": datetime.datetime.now()}
            self.change_history[req_id].append({"old_text": old_text, "developer_id": developer_id, "timestamp": datetime.datetime.now()})
            return True
        else:
            return False

    def get_requirement(self, req_id):
        return self.requirements.get(req_id)

    def get_change_history(self, req_id):
        return self.change_history.get(req_id)

