    def setUp(self):
        self.doorstop = Doorstop()

    def test_store_requirement(self):
        #REQ011, REQ013
        req_id = "REQ001"
        requirement_text = "This is a test requirement."
        developer_id = "dev123"
        self.doorstop.store_requirement(req_id, requirement_text, developer_id)
        stored_req = self.doorstop.get_requirement(req_id)
        self.assertEqual(stored_req["text"], requirement_text)
        self.assertEqual(stored_req["developer_id"], developer_id)
        self.assertIsInstance(stored_req["timestamp"], datetime.datetime)

    def test_update_requirement(self):
        #REQ012, REQ013
        req_id = "REQ001"
        initial_text = "Initial requirement text."
        developer_id_initial = "dev123"
        self.doorstop.store_requirement(req_id, initial_text, developer_id_initial)

        new_text = "Updated requirement text."
        developer_id_update = "dev456"
        success = self.doorstop.update_requirement(req_id, new_text, developer_id_update)
        self.assertTrue(success)

        updated_req = self.doorstop.get_requirement(req_id)
        self.assertEqual(updated_req["text"], new_text)
        self.assertEqual(updated_req["developer_id"], developer_id_update)

        change_history = self.doorstop.get_change_history(req_id)
        self.assertEqual(len(change_history), 1)
        self.assertEqual(change_history[0]["old_text"], initial_text)
        self.assertEqual(change_history[0]["developer_id"], developer_id_initial)
        self.assertIsInstance(change_history[0]["timestamp"], datetime.datetime)

    def test_update_nonexistent_requirement(self):
        #REQ012 (negative)
        req_id = "REQ999"
        new_text = "Some text"
        developer_id = "dev789"
        success = self.doorstop.update_requirement(req_id, new_text, developer_id)
        self.assertFalse(success)

    def test_get_nonexistent_requirement(self):
        #REQ011 (negative)
        req_id = "REQ999"
        req = self.doorstop.get_requirement(req_id)
        self.assertIsNone(req)

    def test_scalability(self):
        #REQ014
        num_requirements = 1000
        for i in range(num_requirements):
            req_id = f"REQ{i:03d}"
            self.doorstop.store_requirement(req_id, f"Requirement {i}", "dev001")

        for i in range(num_requirements):
            req_id = f"REQ{i:03d}"
            self.assertIn(req_id, self.doorstop.requirements)

    def test_lightweight_installation(self):
        #REQ015 - This is difficult to test directly without knowing the installation process.
        # We'll simulate a lightweight installation by checking that the Doorstop class can be instantiated
        # without external dependencies (beyond standard library).  This is a weak test, but the best we can do
        # given the requirement's vagueness.
        try:
            doorstop = Doorstop()
            self.assertTrue(True) # If instantiation succeeds, the test passes.
        except Exception as e:
            self.fail(f"Lightweight installation failed: {e}")

